import { defineConfig } from 'astro/config';
import fs from 'node:fs';

// Serving over HTTPS is not optional for phone testing: browsers block
// getUserMedia (camera + microphone) on any origin that is not HTTPS or
// localhost, so an http:// LAN address gives the assistant no eyes and no
// ears. `npm run dev:mobile` sets MOBILE=1 and picks up the certificate
// generated by scripts/setup_mobile.py.
const useHttps = process.env.MOBILE === '1';
const certDir = new URL('../certs/', import.meta.url);
const keyPath = new URL('dev-key.pem', certDir);
const certPath = new URL('dev-cert.pem', certDir);

const httpsOptions =
  useHttps && fs.existsSync(keyPath) && fs.existsSync(certPath)
    ? { key: fs.readFileSync(keyPath), cert: fs.readFileSync(certPath) }
    : undefined;

if (useHttps && !httpsOptions) {
  console.warn(
    '[sfcc] MOBILE=1 but no certificate found. Run: python scripts/setup_mobile.py',
  );
}

export default defineConfig({
  output: 'static',
  server: {
    // 0.0.0.0 so the phone can reach it; localhost-only would be invisible.
    host: useHttps ? true : 'localhost',
    port: 4321,
  },
  vite: {
    server: {
      https: httpsOptions,
      host: useHttps ? true : undefined,
    },
  },
});
